static void snd_mixart_process_msg ( struct mixart_mgr * mgr ) { struct mixart_msg resp ; u32 msg , addr , type ; int err ; while ( mgr -> msg_fifo_readptr != mgr -> msg_fifo_writeptr ) { msg = mgr -> msg_fifo [ mgr -> msg_fifo_readptr ] ; mgr -> msg_fifo_readptr ++ ; mgr -> msg_fifo_readptr %= MSG_FIFO_SIZE ; addr = msg & ~ MSG_TYPE_MASK ; type = msg & MSG_TYPE_MASK ; switch ( type ) { case MSG_TYPE_ANSWER : resp . message_id = 0 ; resp . data = mixart_msg_data ; resp . size = sizeof ( mixart_msg_data ) ; err = get_msg ( mgr , & resp , addr ) ; switch ( resp . message_id ) { case MSG_STREAM_START_INPUT_STAGE_PACKET : case MSG_STREAM_START_OUTPUT_STAGE_PACKET : case MSG_STREAM_STOP_INPUT_STAGE_PACKET : case MSG_STREAM_STOP_OUTPUT_STAGE_PACKET : if ( mixart_msg_data [ 0 ] ) { dev_err ( & mgr -> pci -> dev , "error MSG_STREAM_ST***_***PUT_STAGE_PACKET status=%x\n" , mixart_msg_data [ 0 ] ) ; } break ; default : dev_dbg ( & mgr -> pci -> dev , "received mf(%x) : msg_id(%x) uid(%x, %x) size(%zd)\n" , msg , resp . message_id , resp . uid . object_id , resp . uid . desc , resp . size ) ; break ; } break ; case MSG_TYPE_NOTIFY : case MSG_TYPE_COMMAND : default : dev_err ( & mgr -> pci -> dev , "doesn't know what to do with message %x\n" , msg ) ; } atomic_dec ( & mgr -> msg_processed ) ; } } 